#include <cstdio>
using namespace std;

#define LL long long
#define ROOP() while (true)

int main() {
    ROOP() {
        int N, M, S;
        scanf("%d %d %d", &N, &M, &S); // Use scanf for input
        if (N == 0) return 0;

        int dp[50][3001] = {};
        dp[0][0] = 1;

        for (int i = 1; i <= M; i++) {
            for (int j = N * N; j >= 1; j--) {
                for (int k = S; k >= i; k--) { 
                    dp[j][k] = (dp[j][k] + dp[j - 1][k - i]) % 100000;
                }
            }
        }
        printf("%d\n", dp[N * N][S]); // Using printf for output
    }
    return 0;
}

