int main() {
    ROOP() {
        int N, M, S;
        scanf("%d %d %d", &N, &M, &S); // Using scanf for faster input
        if (N == 0) return 0;

        // Use a single contiguous memory block for the dp array
        int* dp = new int[(N * N + 1) * (S + 1)]();
        dp[0 * (S + 1) + 0] = 1;

        for (int i = 1; i <= M; i++) {
            for (int j = N * N; j >= 1; j--) {
                for (int k = S; k >= i; k--) {
                    dp[j * (S + 1) + k] = (dp[j * (S + 1) + k] + dp[(j - 1) * (S + 1) + (k - i)]) % 100000;
                }
            }
        }
        printf("%d\n", dp[N * N * (S + 1) + S]);

        // Free allocated memory
        delete[] dp;
    }
    return 0;
}

